DROP TABLE IF EXISTS `english_note`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `english_note` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `note_date` date NOT NULL COMMENT '笔记日期',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '笔记标题',
  `source` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源，如课堂/口语/自学',
  `summary` text COLLATE utf8mb4_unicode_ci COMMENT '整篇笔记摘要',
  `share_status` tinyint NOT NULL DEFAULT '0' COMMENT '共享状态：0-私有，1-共享',
  `priority_order` int NOT NULL DEFAULT '0' COMMENT '排序值，越小越靠前',
  `created_by` bigint NOT NULL COMMENT '创建人ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint DEFAULT NULL COMMENT '修改人ID',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_note_date` (`note_date`),
  KEY `idx_share_status` (`share_status`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='英文学习笔记主表';
