DROP TABLE IF EXISTS `english_note_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `english_note_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `note_id` bigint unsigned NOT NULL COMMENT '所属笔记ID',
  `item_order` int NOT NULL DEFAULT '0' COMMENT '块内排序，越小越靠前',
  `item_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'note_block' COMMENT '内容类型：sentence/phrase/vocab/grammar/example/chunk/note_block',
  `item_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '知识点标题',
  `raw_text` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始整块内容',
  `english_text` longtext COLLATE utf8mb4_unicode_ci COMMENT '英文主内容',
  `chinese_text` longtext COLLATE utf8mb4_unicode_ci COMMENT '中文主内容',
  `explanation` longtext COLLATE utf8mb4_unicode_ci COMMENT '解释说明',
  `examples` longtext COLLATE utf8mb4_unicode_ci COMMENT '例句或补充示例',
  `example_image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图例图片URL或相对路径',
  `example_image_alt` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图例图片说明',
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关键词，逗号分隔',
  `share_status` tinyint NOT NULL DEFAULT '0' COMMENT '共享状态：0-私有，1-共享',
  `priority_order` int NOT NULL DEFAULT '0' COMMENT '排序值，越小越靠前',
  `created_by` bigint NOT NULL COMMENT '创建人ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint DEFAULT NULL COMMENT '修改人ID',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_note_id` (`note_id`),
  KEY `idx_item_type` (`item_type`),
  KEY `idx_item_order` (`note_id`,`item_order`),
  KEY `idx_share_status` (`share_status`),
  KEY `idx_priority_order` (`priority_order`),
  CONSTRAINT `fk_english_note_item_note_id` FOREIGN KEY (`note_id`) REFERENCES `english_note` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1607 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='英文学习笔记分段表';
