INSERT INTO `interview_category` VALUES (1,'Teamwork','teamwork','Questions about teamwork and collaboration',1,1,1,'2026-04-07 14:26:23',1,'2026-04-07 14:26:23'),(2,'Communication','communication','Questions about communication skills',2,1,1,'2026-04-07 14:26:23',1,'2026-04-07 14:26:23'),(3,'Conflict Handling','conflict_handling','Questions about handling disagreements',3,1,1,'2026-04-07 14:26:23',1,'2026-04-07 14:26:23'),(4,'Problem Solving','problem_solving','Questions about solving problems',4,1,1,'2026-04-07 14:26:23',1,'2026-04-07 14:26:23'),(5,'Leadership','leadership','Questions about leadership and initiative',5,1,1,'2026-04-07 14:26:23',1,'2026-04-07 14:26:23'),(6,'Behavioral','behavioral','General behavioral interview questions',6,1,1,'2026-04-07 14:26:23',1,'2026-04-07 14:26:23'),(7,'Java Foundation','Java Foundation','The basic theory fundation',7,1,1,'2026-04-16 07:02:36',1,'2026-04-16 07:02:36'),(8,'Spring & Spring Boot & Spring cloud','Spring','Spring knowledge',8,1,1,'2026-04-16 07:03:32',1,'2026-04-16 07:03:32'),(9,'Kafka','Kafka','Kafka advanced knowledge',9,1,1,'2026-04-16 07:08:47',1,'2026-04-16 07:08:47'),(10,'Redis','Redis','Redis advanced knowledge',10,1,1,'2026-04-16 07:08:47',1,'2026-04-16 07:08:47'),(11,'Mysql','Mysql','Mysql advanced knowledge',11,1,1,'2026-04-16 07:08:47',1,'2026-04-16 07:08:47'),(12,'Network','Network','Network basic knowledge',12,1,1,'2026-04-16 07:08:47',1,'2026-04-16 07:08:47');
