DROP TABLE IF EXISTS `interview_question`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `interview_question` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `category_id` bigint unsigned NOT NULL COMMENT '分类ID',
  `question` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '英文面试题',
  `question_cn` text COLLATE utf8mb4_unicode_ci COMMENT '中文释义',
  `short_answer` text COLLATE utf8mb4_unicode_ci COMMENT '简短回答',
  `full_answer` longtext COLLATE utf8mb4_unicode_ci COMMENT '完整回答',
  `answer_tip` text COLLATE utf8mb4_unicode_ci COMMENT '答题提示',
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关键词',
  `difficulty_level` tinyint NOT NULL DEFAULT '1' COMMENT '难度：1-基础，2-中等，3-进阶',
  `share_status` tinyint NOT NULL DEFAULT '0' COMMENT '共享状态：0-私有，1-共享',
  `priority_order` int NOT NULL DEFAULT '0' COMMENT '排序值',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1-启用，0-禁用',
  `created_by` bigint NOT NULL COMMENT '创建人ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_share_status` (`share_status`),
  KEY `idx_priority_order` (`priority_order`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='面试题主表';
