INSERT INTO `kids_english_card` VALUES (1,'northeast','东北部','/ˌnɔːrθˈiːst/','noun','Core','north · east','north-EAST','or → /ɔːr/; ea → /iː/','拆分练习：north / east。注意：or → /ɔːr/; ea → /iː/。','Unit 1 · 1',NULL,'/static/uploads/kids_cards/northeast-wide.png','Chunk it: north · east. Focus on or → /ɔːr/; ea → /iː/.',1,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:15:07'),(2,'beach','海滩；沙滩','/biːtʃ/','noun','Core','beach','BEACH','ea → /iː/; tch → /tʃ/','拆分练习：beach。注意：ea → /iː/; tch → /tʃ/。','Unit 1 · 1',NULL,'/static/uploads/kids_cards/beach-wide.png','Chunk it: beach. Focus on ea → /iː/; tch → /tʃ/.',2,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(3,'wonderful','极好的；精彩的','/ˈwʌndərfəl/','adjective','Core','won · der · ful','WON-der-ful','o → /ʌ/ in won; -ful → /fəl/','拆分练习：won / der / ful。注意：o → /ʌ/ in won; -ful → /fəl/。','Unit 1 · 1',NULL,'/static/uploads/kids_cards/wonderful-wide.png','Chunk it: won · der · ful. Focus on o → /ʌ/ in won; -ful → /fəl/.',3,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(4,'safety','安全','/ˈseɪfti/','noun','Core','safe · ty','SAFE-ty','a_e → /eɪ/; y → /iː/','拆分练习：safe / ty。注意：a_e → /eɪ/; y → /iː/。','Unit 1 · 1',NULL,'/static/uploads/kids_cards/safety-wide.png','Chunk it: safe · ty. Focus on a_e → /eɪ/; y → /iː/.',4,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(5,'rule','规则；条例','/ruːl/','noun','Core','rule','RULE','u_e → /uː/; final e silent','拆分练习：rule。注意：u_e → /uː/; final e silent。','Unit 1 · 1',NULL,'/static/uploads/kids_cards/rule-wide.png','Chunk it: rule. Focus on u_e → /uː/; final e silent.',5,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(6,'meaningful','有意义的','/ˈmiːnɪŋfəl/','adjective','Core','mean · ing · ful','MEAN-ing-ful','ea → /iː/; -ing → /ɪŋ/','拆分练习：mean / ing / ful。注意：ea → /iː/; -ing → /ɪŋ/。','Unit 1 · 2',NULL,'/static/uploads/kids_cards/meaningful-wide.png','Chunk it: mean · ing · ful. Focus on ea → /iː/; -ing → /ɪŋ/.',6,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(7,'National Library of China','中国国家图书馆','/ˈnæʃənəl ˈlaɪbreri əv ˈtʃaɪnə/','proper noun','Core','Na · tion · al Li · bra · ry of Chi · na','NAT-ion-al LIB-rar-y of CHI-na','tion → /ʃən/; br → /br/; ch → /tʃ/','拆分练习：Na / tion / al Li / bra / ry of Chi / na。注意：tion → /ʃən/; br → /br/; ch → /tʃ/。','Unit 1 · 2',NULL,'/static/uploads/kids_cards/national-library-of-china-wide.png','Chunk it: Na · tion · al Li · bra · ry of Chi · na. Focus on tion → /ʃən/; br → /br/; ch → /tʃ/.',7,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(8,'on foot','走路；步行','/ɒn fʊt/','phrase','Core','on foot','ON FOOT','oo → /ʊ/ in foot','拆分练习：on foot。注意：oo → /ʊ/ in foot。','Unit 1 · 2',NULL,'/static/uploads/kids_cards/on-foot-wide.png','Chunk it: on foot. Focus on oo → /ʊ/ in foot.',8,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(9,'China Science and Technology Museum','中国科学技术馆','/ˈtʃaɪnə ˈsaɪəns ənd tekˈnɒlədʒi mjuˈziːəm/','proper noun','Core','Chi · na Sci · ence and Tech · nol · o · gy Mu · se · um','CHI-na SCI-ence and tech-NOL-o-gy mu-SE-um','ch → /tʃ/; c → /s/ in science; -gy → /dʒi/','拆分练习：Chi / na Sci / ence and Tech / nol / o / gy Mu / se / um。注意：ch → /tʃ/; c → /s/ in science; -gy → /dʒi/。','Unit 1 · 2',NULL,'/static/uploads/kids_cards/china-science-and-technology-museum-wide.png','Chunk it: Chi · na Sci · ence and Tech · nol · o · gy Mu · se · um. Focus on ch → /tʃ/; c → /s/ in science; -gy → /dʒi/.',9,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(10,'far from','离……远','/fɑːr frəm/','phrase','Core','far from','FAR from','ar → /ɑːr/; from → /frəm/','拆分练习：far from。注意：ar → /ɑːr/; from → /frəm/。','Unit 1 · 2',NULL,'/static/uploads/kids_cards/far-from-wide.png','Chunk it: far from. Focus on ar → /ɑːr/; from → /frəm/.',10,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(11,'baby','动物幼崽；婴儿','/ˈbeɪbi/','noun','Core','ba · by','BA-by','a → /eɪ/; y → /i/','拆分练习：ba / by。注意：a → /eɪ/; y → /i/。','Unit 1 · 3',NULL,'/static/uploads/kids_cards/baby-wide.png','Chunk it: ba · by. Focus on a → /eɪ/; y → /i/.',11,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(12,'chick','小鸡','/tʃɪk/','noun','Core','chick','CHICK','ch → /tʃ/; ck → /k/','拆分练习：chick。注意：ch → /tʃ/; ck → /k/。','Unit 1 · 3',NULL,'/static/uploads/kids_cards/chick-wide.png','Chunk it: chick. Focus on ch → /tʃ/; ck → /k/.',12,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(13,'sometimes','有时','/ˈsʌmtaɪmz/','adverb','Core','some · times','SOME-times','o → /ʌ/ in some; i_e → /aɪ/','拆分练习：some / times。注意：o → /ʌ/ in some; i_e → /aɪ/。','Unit 1 · 3',NULL,'/static/uploads/kids_cards/sometimes-wide.png','Chunk it: some · times. Focus on o → /ʌ/ in some; i_e → /aɪ/.',13,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(14,'go fishing','去钓鱼','/ɡoʊ ˈfɪʃɪŋ/','phrase','Core','go fish · ing','GO FISH-ing','o → /oʊ/; sh → /ʃ/; -ing → /ɪŋ/','拆分练习：go fish / ing。注意：o → /oʊ/; sh → /ʃ/; -ing → /ɪŋ/。','Unit 1 · 3',NULL,'/static/uploads/kids_cards/go-fishing-wide.png','Chunk it: go fish · ing. Focus on o → /oʊ/; sh → /ʃ/; -ing → /ɪŋ/.',14,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(15,'daytime','白天','/ˈdeɪtaɪm/','noun','Core','day · time','DAY-time','ay → /eɪ/; i_e → /aɪ/','拆分练习：day / time。注意：ay → /eɪ/; i_e → /aɪ/。','Unit 1 · 4',NULL,'/static/uploads/kids_cards/daytime-wide.png','Chunk it: day · time. Focus on ay → /eɪ/; i_e → /aɪ/.',15,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(16,'university','大学','/ˌjuːnɪˈvɜːrsəti/','noun','Core','u · ni · ver · si · ty','u-ni-VER-si-ty','u → /juː/; er → /ər/; -ity → /əti/','拆分练习：u / ni / ver / si / ty。注意：u → /juː/; er → /ər/; -ity → /əti/。','Unit 1 · 4',NULL,'/static/uploads/kids_cards/university-wide.png','Chunk it: u · ni · ver · si · ty. Focus on u → /juː/; er → /ər/; -ity → /əti/.',16,1,NULL,'2026-09-04 15:10:43',NULL,'2026-09-04 20:14:54'),(17,'Toronto','多伦多','/təˈrɒntoʊ/','proper noun','Core','To · ron · to','to-RON-to','o → /ɒ/; final o → /oʊ/','拆分练习：To / ron / to。注意：o → /ɒ/; final o → /oʊ/。',