--
-- Table structure for table `vocabulary_library`
--

DROP TABLE IF EXISTS `vocabulary_library`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vocabulary_library` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `category` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类，如 computer / daily english / academic / business / cloud / programming',
  `term` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '词汇、短语或句子',
  `chinese_meaning` text COLLATE utf8mb4_unicode_ci COMMENT '中文解释',
  `english_note` text COLLATE utf8mb4_unicode_ci COMMENT '英文说明或补充',
  `example_sentence` text COLLATE utf8mb4_unicode_ci COMMENT '例句',
  `extra_note` text COLLATE utf8mb4_unicode_ci COMMENT '额外备注',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_term` (`term`)
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
